package com.v2ray.ang.uiimport android.content.Intentimport android.content.SharedPreferencesimport android.net.Uriimport android.os.Bundleimport android.text.TextUtilsimport android.util.Logimport android.view.Viewimport android.widget.Toastimport androidx.appcompat.app.AlertDialogimport androidx.appcompat.app.AppCompatActivityimport androidx.lifecycle.lifecycleScopeimport com.v2ray.ang.AppConfigimport com.v2ray.ang.Rimport com.v2ray.ang.databinding.ActivityLoginBindingimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.launchimport kotlinx.coroutines.withContextimport org.json.JSONObjectimport java.io.BufferedReaderimport java.io.InputStreamReaderimport java.io.OutputStreamimport java.net.HttpURLConnectionimport java.net.URLclass LoginActivity : AppCompatActivity() {    private lateinit var binding: ActivityLoginBinding    private lateinit var sharedPreferences: SharedPreferences    companion object {        private const val TAG = "LoginActivity"        private const val PREF_NAME = "xiexie_vpn_prefs"        private const val KEY_UUID = "saved_uuid"        private const val KEY_AUTO_LOGIN = "auto_login"    }    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        binding = ActivityLoginBinding.inflate(layoutInflater)        setContentView(binding.root)        sharedPreferences = getSharedPreferences(PREF_NAME, MODE_PRIVATE)        setupUI()        checkAutoLogin()    }    private fun setupUI() {        binding.btnLogin.setOnClickListener {            val uuid = binding.etUuid.text.toString().trim()            if (uuid.isNotEmpty()) {                performLogin(uuid)            } else {                Toast.makeText(this, getString(R.string.login_prompt), Toast.LENGTH_SHORT).show()            }        }        binding.tvRegisterLink.setOnClickListener {            val locale = resources.configuration.locales[0].language            val url = if (locale == "zh") {                "https:            } else {                "https:            }            val intent = Intent(Intent.ACTION_VIEW).apply {                data = Uri.parse(url)            }            startActivity(intent)        }        val savedUuid = sharedPreferences.getString(KEY_UUID, "")        if (!savedUuid.isNullOrEmpty()) {            binding.etUuid.setText(savedUuid)            binding.cbAutoLogin.isChecked = sharedPreferences.getBoolean(KEY_AUTO_LOGIN, false)        }    }    private fun checkAutoLogin() {        val autoLogin = sharedPreferences.getBoolean(KEY_AUTO_LOGIN, false)        val savedUuid = sharedPreferences.getString(KEY_UUID, "")        if (autoLogin && !savedUuid.isNullOrEmpty()) {            binding.etUuid.setText(savedUuid)            binding.cbAutoLogin.isChecked = true            performLogin(savedUuid)        }    }    private fun performLogin(uuid: String) {        setLoading(true)        lifecycleScope.launch {            try {                val result = withContext(Dispatchers.IO) {                    loginRequest(uuid)                }                withContext(Dispatchers.Main) {                    setLoading(false)                    when (result) {                        200 -> {                            saveLoginInfo(uuid)                            navigateToMainActivity()                        }                        400, 401, 404 -> {                            Toast.makeText(this@LoginActivity, "无效的访问代码", Toast.LENGTH_SHORT).show()                            clearSavedLogin()                        }                        403 -> {                            Toast.makeText(this@LoginActivity, "访问代码已过期", Toast.LENGTH_SHORT).show()                            clearSavedLogin()                        }                        else -> {                            Toast.makeText(this@LoginActivity, "服务器错误，请稍后重试", Toast.LENGTH_SHORT).show()                        }                    }                }            } catch (e: Exception) {                withContext(Dispatchers.Main) {                    setLoading(false)                    Log.e(TAG, "Login failed", e)                    Toast.makeText(this@LoginActivity, "网络连接失败: ${e.message}", Toast.LENGTH_LONG).show()                }            }        }    }    private fun loginRequest(uuid: String): Int {        val jsonObject = JSONObject().apply { put("code", uuid) }        val payloadBytes = jsonObject.toString().toByteArray(Charsets.UTF_8)        var lastException: Exception? = null        var lastResponseCode = -1        for ((index, baseUrl) in AppConfig.API_ENDPOINTS.withIndex()) {            val timeoutMs = if (index == 0) 6000 else 8000            var connection: HttpURLConnection? = null            try {                val url = URL("$baseUrl/login")                connection = url.openConnection() as HttpURLConnection                connection.requestMethod = "POST"                connection.setRequestProperty("Content-Type", "application/json")                connection.setRequestProperty("Accept", "application/json")                connection.doOutput = true                connection.connectTimeout = timeoutMs                connection.readTimeout = timeoutMs                connection.outputStream.use { os: OutputStream ->                    os.write(payloadBytes, 0, payloadBytes.size)                }                val responseCode = connection.responseCode                Log.d(TAG, "Login response code ($baseUrl): $responseCode")                if (responseCode in 200..299 || responseCode in 400..499) {                    return responseCode                }                lastResponseCode = responseCode            } catch (e: Exception) {                Log.w(TAG, "Login request failed on $baseUrl", e)                lastException = e            } finally {                connection?.disconnect()            }        }        if (lastResponseCode != -1) {            return lastResponseCode        }        throw lastException ?: RuntimeException("Network error")    }    private fun saveLoginInfo(uuid: String) {        val editor = sharedPreferences.edit()        if (binding.cbAutoLogin.isChecked) {            editor.putString(KEY_UUID, uuid)            editor.putBoolean(KEY_AUTO_LOGIN, true)        } else {            editor.remove(KEY_UUID)            editor.putBoolean(KEY_AUTO_LOGIN, false)        }        editor.apply()    }    private fun clearSavedLogin() {        val editor = sharedPreferences.edit()        editor.remove(KEY_UUID)        editor.putBoolean(KEY_AUTO_LOGIN, false)        editor.apply()        binding.cbAutoLogin.isChecked = false    }    private fun setLoading(isLoading: Boolean) {        binding.progressBar.visibility = if (isLoading) View.VISIBLE else View.GONE        binding.btnLogin.isEnabled = !isLoading        binding.etUuid.isEnabled = !isLoading        binding.cbAutoLogin.isEnabled = !isLoading    }    private fun navigateToMainActivity() {        val intent = Intent(this, MainActivity::class.java)        intent.putExtra("user_uuid", binding.etUuid.text.toString().trim())        startActivity(intent)        finish()    }}